pub fn is_non_prime(n: u64) -> bool {
    // n is assumed to be >= 2
    if n <= 3 {
        return false;
    }
    if n % 2 == 0 {
        return true; // even and > 2
    }

    // Check odd divisors up to sqrt(n)
    let mut d: u64 = 3;
    while d <= n / d {
        if n % d == 0 {
            return true;
        }
        d += 2;
    }
    false
}